-- =====================================================================
-- SIGAF · Migración histórica — Lote 1: 91 facturas (Grupos A+B)
-- Generado desde historico/ (pestaña "integrales") + reporte OOAD.
-- 14 enriquecidas con OOAD (comprobante + fecha pago real); 77 con fecha de factura de respaldo.
-- Suma importe_factura = $42,266,670.40
-- Supuestos: periodo_inicio/fin = primer/último día del mes asignado (el texto
--   libre de "periodo" no se parseó). tasa_iva por defecto (0.16). created_by null.
--   FKs resueltas con un JOIN LATERAL contra contratos que elige 1 sola fila:
--   si numero_interno está duplicado (IGSA 050GYR032N03825-055-00, dos vigencias)
--   desempata por la vigencia que contiene la fecha real de la factura.
-- =====================================================================
begin;

-- Silenciar triggers de M1 durante la carga: el de historial auto-inserta
-- un renglón 'general' con fecha = ahora; aquí escribimos el historial a mano
-- con las fechas reales. El de auto en_revision no aplica (ninguna 'capturada').
alter table facturas disable trigger trg_a_historial;
alter table facturas disable trigger trg_b_auto_en_revision;

-- 1) Facturas. El JOIN LATERAL 'c' devuelve exactamente 1 contrato por factura
--    (limit 1); si hay dos vigencias con el mismo numero_interno, prioriza la
--    que contiene v.fecha_ref. capitulo_id se deriva de la partida del contrato.
insert into facturas
  (folio_ingreso, folio_proveedor, capitulo_id, partida_id, contrato_id, proveedor_id,
   periodo_inicio, periodo_fin, mes_asignado, anio_asignado, importe_factura,
   estatus_general, estatus_firmas, estatus_pedido_recepcion, comprobante_ooad)
select v.folio_ingreso, v.folio_proveedor,
  pa.capitulo_id, c.partida_id, c.id, c.proveedor_id,
  v.periodo_inicio, v.periodo_fin, v.mes_asignado, v.anio_asignado, v.importe_factura,
  v.estatus_general::estatus_general, v.estatus_firmas::estatus_firmas, v.estatus_pedido_recepcion::estatus_pedido_recepcion, v.comprobante_ooad
from (values
  ('HGZ2-INT-HIST-001', 'EF577566', '050GYR988T00925-001-00', '2026-01-28'::date, '2026-01-01'::date, '2026-01-31'::date, 1, 2026, 86304.96, 'gasto_reflejado', 'autorizada_admin_contrato', 'generado', null),
