) as v(folio_ingreso, folio_proveedor, contrato, fecha_ref, periodo_inicio, periodo_fin, mes_asignado, anio_asignado, importe_factura, estatus_general, estatus_firmas, estatus_pedido_recepcion, comprobante_ooad)
join lateral (
  select c.* from contratos c
  where c.numero_interno = v.contrato
  order by (case when v.fecha_ref between c.vigencia_inicio and c.vigencia_fin then 0 else 1 end), c.vigencia_inicio
  limit 1
) c on true
join partidas pa on pa.id = c.partida_id;

